<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);$checks=[];
$read=static function(string $path)use($root):string{$file=$root.'/'.ltrim($path,'/');return is_file($file)?(string)file_get_contents($file):'';};
$add=static function(string $label,bool $ok)use(&$checks):void{$checks[]=['label'=>$label,'passed'=>$ok,'points'=>$ok?4:0];};
$has=static fn(string $content,string $needle):bool=>str_contains($content,$needle);
$sql=$read('database/20260722_creator_campaign_crm_lifecycle_v12_single_install.sql');
$definitions=$read('includes/creator-campaigns/crm-definitions.php');
$repository=$read('includes/creator-campaigns/crm-repository.php');
$service=$read('includes/creator-campaigns/crm-service.php');
